from dental_release.paths import expand as _release_expand
from codesign import *
import csv, collections

def main():
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    result = read(ROOT / 'results.json')
    r1 = read(ROOT / 'RESULTS_R1.json')
    r3 = read(ROOT / 'RESULTS_R3.json')
    facit = read(ROOT / 'raw/EXTERNAL_FACIT.json')
    rows = result['designs']
    (fig, ax) = plt.subplots(1, 3, figsize=(16, 5), layout='constrained')
    x = np.arange(len(rows))
    a = [r['regions']['intaglio']['found'] / 16 for r in rows]
    b = [r['regions']['margin_band']['found'] / 16 for r in rows]
    ax[0].bar(x - 0.18, a, 0.36, label='Intaglio')
    ax[0].bar(x + 0.18, b, 0.36, label='Margin band')
    ax[0].set_xticks(x, [r['id'].replace('crownloop_', '').replace('full_', 'Full ') for r in rows], rotation=55, ha='right')
    ax[0].set_ylim(0, 1)
    ax[0].set_ylabel('Conditional local witnesses / 16 points')
    ax[0].legend(fontsize=8)
    ax[0].set_title('Own designs: coupled access + 1 N\nPER_POINT samples; physical UNKNOWN')
    ts = result['tool_mechanics']
    ax[1].barh([t['id'] for t in ts], [t['force_max_N'] for t in ts])
    ax[1].axvline(1, color='red', ls='--', label='Declared 1 N')
    ax[1].set_xlabel('Allowed force [N], solid-beam scenario')
    ax[1].set_title('Inverse tool + holder requirement\n20 µm final error, 5 µm reserve')
    ax[1].legend(fontsize=8)
    ff = facit['rows'][1:]
    xx = np.arange(3)
    means = [f['mean_RMS_um'] for f in ff]
    errors = np.array([[f['mean_RMS_um'] - f['CI95_um'][0] for f in ff], [f['CI95_um'][1] - f['mean_RMS_um'] for f in ff]])
    ax[2].bar(xx, means, color='#cc8833')
    ax[2].errorbar(xx, means, yerr=errors, fmt='none', color='black', capsize=4)
    ax[2].axhline(20, color='red', ls='--', label='Declared 20 µm scenario')
    ax[2].set_xticks(xx, [f['region'].replace(' region', '') for f in ff])
    ax[2].set_ylabel('Published regional mean RMS [µm]')
    ax[2].set_title('Independent milled PMMA crowns, n=15\nTable 1, DOI 10.3390/healthcare9080983')
    ax[2].legend(fontsize=8)
    fig.suptitle('X89: local milling requirements; published RMS does not isolate tool bending', fontsize=13)
    (ROOT / 'figures').mkdir(exist_ok=True)
    fig.savefig(ROOT / 'figures/MILLING_CODESIGN.png', dpi=170)
    fig.savefig(ROOT / 'figures/MILLING_CODESIGN.pdf')
    plt.close(fig)
    table = '| Design | Intaglio | Marginalband | Answer |\n|---|---:|---:|---|\n'
    for r in rows:
        table += f"| {r['id']} | {r['regions']['intaglio']['found']}/16 | {r['regions']['margin_band']['found']}/16 | Conditional local witnesses; physical UNKNOWN |\n"
    tools = '| Mill | Slim length from physical tip, mm | Point input voltage, mm | Max force , N | Max retention at 1 N , µm / N |\n|---|---:|---:|---:|---:|\n'
    for t in ts:
        tools += f"| {t['id']} | {t['neck_length_physical_tip_mm']:.2f} | {t['tip_to_clamp_mm']:.2f} | {t['force_max_N']:.4f} | {t['holder_compliance_max_mm_N'] * 1000:.3f} |\n"
    text = '# The crown indicates the Mill and stiffness requirement\n\nAn exported crown now receives a local milling rule in the design gate: tool witness, required neck diameter, permissible cutting force and maximum holding resuscitability for a declared error budget. The rule alerts when the library has no witness at any point. It retains previously FAIL and leaves physical manufacturing UNKNOWN.\n\nRun from this directory:\n\n```bash\n./run_all.sh\n```\n\nA command restores three designs, controls and figure, without downloads. The Python environment is the existing cad-to-simulation/.venv-newton on this machine. The package requires the hashbound local predecessors and their geometry; it is not a portable lab installation.\n\n' + table + "\nEach cell is PER_POINT, 16 area-weighted points in the region. Five crown loop designer and three R4 helmrons are read. Intaglio and margin tapes retain local facet-ID , coordinates, normal, pose and error intervals in the data files. Margin_band is a declared geometric band or the source's annulus, no measured anatomical margin. All found the smallest library witnesses in this scenario using nominal tip diameter 0,6 mm . The entire surface access and the smallest global tool is UNKNOWN; the absence of witness on the posegall is not a global impossibility.\n\n" + tools + _release_expand("\nThe table is PHENOMENOLOGICAL where force , 572 GPa module, circular solid neck, 1 µm / N holders and 0,8 sinter scale are adopted. Geometry tested at PER_POINT. The Negative highest holding flexibility means that no more rigid holding selection is sufficient with the exact assumed neck profile at 1 N. The height of the source card is pointed; the geometry code works from the ball centre and corrects the radius. Real flutes, installed length and holder form lack metrology.\n\nThe error budget is 20 µm in final scale with 5 µm otherwise geometry errors. It reuses X13 : s experimental fault criteria as an engineering scenario, not a clinical cement limit. The Tool path is moved outwards with the upper displacement, and the entire sweep is extended with the same error. It gives local stock within [offset − u, offset+u]; double budget consumption protects both fault marks. The rigorous analytical enclosure applies to declared statik/ geometry and u<kulradien. Rigorous outward-rounded floating point enclosure is missing.\n\n## External reference and what is not holds\n\n[Published Table  1 ](https://doi.org/10.3390/healthcare9080983) measures  CAD - to the-to the intaglio- RMS  i  15   PMMA - crowns : marginalt  45,2   ±   8,2   µm , axialt  50,5   ±   8,3   µm  and  occlusal   36,9   ±   4,4   µm ; entire intaglio  44,8   ±   5,5   µm . This is PER_SURFACE_REGION group agents, not individual points . The smallest cutter was 0,6 mm. The numbers rejects the broad assumption that small lace diameter alone guarantees ≤ 20 µm milling errors. Our conditional beam model is not calibrated by them: scanners, CAM, materials, misregistration and tools are mixed together. Reference / CI /range and Table ID are available in FACIT.csv and raw/EXTERNAL_FACIT.json. A deliberate ten times for low table report is rejected.\n\nA second [primary source of fully sintered zirconia](https://doi.org/10.3390/mi9030127), Table 2 and Figure 11 – 12 , has cutting force and tool geometry but has no paired crown error and mounted compliance . The power figures are not used as our load data. Two of two source candidates is rejected as calibration facit for the beam; 100 % failure. Table 1 : s 12 method/region entries give four milling entries; eight SLA/DLP entries are rejected for wrong manufacturing regimen, 66,7 % loss. The web was used after the own first calculation; the source sharpened boundary between milling errors and bending. The comparison is retrospective, not blind physical validation.\n\nAll eight crowns lacks paired forces , mounted response, real tool profile, CAM run/fixture, dynamic/runout, batch-bound sinter distortion and continuous surface coverage. Therefore, 8/8 physical qualification is UNKNOWN. Made surface is left as a local HANDOVER start-up state to the cement model; set cement gap or margin pass has not been measured. No clinical recommendation is made.\n\n## Geometry and measured response\n\nAccess and invers beam budget uses the same local geometry. The new geometry representation retains four almost degenerate triangles in two helkronas through conservative segment housing. The usual triangular representation of the predecessor rejected these geometries. The small triangles are only exempted from normal sampling and still participate in the collision control.\n\nA direct measured upper displacement of the mounted tool can replace the nominal beam response in the actual sweep control. The holder does not count again. Each port must match tool/pose and load range. A qualified curvature limit provides the exact rational interpolation residue; missing boundary or extrapolation gives UNKNOWN . The run-off positive port is a synthetic fixture of its own, not a measurement : 4,5 µm top tip shift at 1 N provides 17,201 µm local final stock budget and witness on a flat surface. Missing curvature limit, wrong pose and injected 50 µm response are rejected.\n\nSuitable sample 1 : the exact same diameter, shaft diameter, total length and input position, but other neck length; identity error 0 and downstream bending difference 35,485 µm in final scale. The minimum add-on for this static query is the compliance integral or mounted response with connected force /pose. Specimen 2 : the exact same two loading points, identity error 0 , but 1/512 mm = 1,953125 µm difference between. The minimum addition is an independent curvature limit or a measured response housing. No affinity is extrapolated.\n\nControls : independent quadrature reproduces circular beam response. Injected dual capacity, 100 N , soft holder, spent error budget, 0,2 mm - gap , deleted sliver barrier and sourcehash error are rejected. X49 : s previously M1 - FAIL retained. This verifies the implementation; algorithm superiority is not claimed.\n\n## Run design rule on export\n\n```bash\n./design_gate @DENTAL_IMPLEMENTATIONS@/X1B/exports/D1/crown.stl \\\n  --milling-contract contracts/crownloop_D1.json --output my_gate.json\n```\n\nAdd `--prep`, `--antagonist`, `--contract`, `--units mm` and `--sinter-factor` to run the same X49 triple and add the `milling_codesign` rule. The predecessor's checkout does not change. Return codes: 2 = declared scenario failed , 3 = UNKNOWN , 4 = contract error. The contract binds exactly STL -hash, marked mesh-hash, facet regions, tool cards and scenario. An arbitrary new STL requires its own region/unit contract; no anatomical surface is guessed as qualification. Fill in measurement ports according to LAB_MEASUREMENT_SPEC.md .\n\n## Data and review\n\nKronloopen: existing STS - Tooth3D-derived designer, CC BY 4.0, [dataset](https://doi.org/10.5281/zenodo.10597292). R4 -helmets: Teeth3DS , local mesh license UNKNOWN according to the source's README ; private local reading, no redistribution. R1 : s incorrect Bits2Bites label is corrected separately in SOURCE_CORRECTIONS.json and R2 ; historical raw files are preserved. Bits2Bites, ToothFairy2, MMDental and mandible defects are not used. The two primary articles are CC BY 4.0 . Custom calibration and column geometry are synthetic; no patient records or identifying images are read.\n\nAll data sets are read local during re-use. No large data sets or source trees are copied. Custom files are far below 3 GB and no arrays over 50 MB are written. Costs and hash-bound raw answers are available in results.json. Preparation / search in older jobs and physical lab cost is UNKNOWN . Figure: figures/MILLING_CODESIGN.png/PDF. Status PENDING_INDEPENDENT_REVIEW. Graph dispatch was stopped by an existing Result hash mismatch; local feedback suggestion is retained for the coordinator.\n")
    (ROOT / 'README_DEMO.md').write_text(text)
    opening = "# Local Mill and stiffness rule for exported crowns\n\nA executable rule now connects the crown's local geometry to the library's cutters, neck requirements, allowed force and hold compliance. Eight designer has been tested and previous design errors are retained. Published milling facit shows regional RMS error 36,9 – 50,5 µm ; this prevents our nominal beam scenarios from being used as a promise of 20 µm full manufacturing accuracy.\n\n" + table + '\nAll cells: PER_POINT sampling, declared 1 N scenario, no full crown qualification. Total ' + str(sum((x['found'] for x in rows))) + '/ 256 local witnesses, ' + str(256 - sum((x['found'] for x in rows))) + "/ 256 without library witness in this scenario. Physical qualification UNKNOWN 8 / 8 . Precise numericals, cost, external table cells, negative R1 -outputs, two identity samples and precipitating injections are available in results.json and README_DEMO.md.\n\nStrong control : quadrature and independent triangle distances reproduce declared quantities ; no method gain is claimed. The next essential design is the same tool's measured mounted force displacement housing, one-way CAM-tail specimen and continuous facet protection, according to LAB_MEASUREMENT_SPEC.md.\n"
    (ROOT / 'RESULTS.md').write_text(opening)
    final = "The trial makes the crown's geometry a local condition for Mill, cutting force and holding stiffness.\nA executable X49 extension has been tested on five kronloop designer and three new helkronas.\n" + str(sum((x['found'] for x in rows))) + ' by 256 points has conditional tool witnesses; others provide library alarms in the selected scenario.\nMeasured mounted response can now be used directly in the collision and error budgets; precipitating injections work.\nPublished milling facit shows 36,9 – 50,5 µm regional RMS error and does not calibrate our beam model.\nThe biggest obstacle is missing force, tool, CAM and surface measurement; all eight crowns has physical UNKNOWN .\nThe next design is a mounted response housing, a vertical milling sample and continuous surface coverage.\n'
    (ROOT / 'SOL_NIGHT_FINAL_X89-milling-codesign.md').write_text(final)
    (ROOT / 'HANDOFF_R3.md').write_text(opening + '\nOne command: ./run_all.sh. R3 positive fixture is synthetic and response port is not clinically/physically validated. Next: same-tool installed response measured across declared force/pose envelope, dynamometer force upper with bandwidth, full CAM/fixture scene, scanned held-out part and local manufacturing->cement handover. No canonical graph/source checkout changed.\n')
    (ROOT / 'HANDOFF.md').write_text((ROOT / 'HANDOFF_R3.md').read_text())
    dump(ROOT / 'ATTEMPTS.json', [dict(round='R1', outcome='Conditional inverse tool mechanics;2 full crowns rejected; original missing triangle handling preserved', next='Mixed-dimensional retained obstacle cover'), dict(round='R2', outcome='All8 queried;5 original rowsets unchanged; exact calibration insufficiency and external source scope measured', next='Installed response consumed by geometric sweep'), dict(round='R3', outcome='Actual gate extension; source/physics/geometry fault injections and parent FAIL preserve', next='Acquire matched force-response/CAM-heldout observations and close surface coverage')])
    print('README, results summary and figure written')
if __name__ == '__main__':
    main()
